import * as THREE from 'three/webgpu';
import { texture } from 'three/tsl';
import { MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load ceramic grain texture
  const tex = ctx.textureLoader.load(config.assets.imageUrl);
  tex.colorSpace = THREE.SRGBColorSpace;

  // Create plane geometry with atlas region aspect ratio (512:320 = 1.6:1)
  const planeHeight = 0.8;
  const planeWidth = planeHeight * (512 / 320);
  const geom = new THREE.PlaneGeometry(planeWidth, planeHeight);

  // TSL material with texture node
  const texNode = texture(tex);
  const mat = new MeshBasicNodeMaterial({
    colorNode: texNode,
    side: THREE.DoubleSide,
  });

  const plane = new THREE.Mesh(geom, mat);
  group.add(plane);

  // Render text using fontAtlas
  if (ctx.fontAtlas && config.textContent?.length) {
    const textStr = config.textContent[0];
    const textGeom = ctx.fontAtlas.createGeometry({
      text: textStr,
      fontSize: 0.34, // Headline size from design tokens
      anchor: [0.5, 0.5],
    });
    const textMat = ctx.fontAtlas.createMaterial({
      color: 0xe8ecf2, // paper color
    });
    const textMesh = new THREE.Mesh(textGeom, textMat);
    textMesh.position.z = 0.1;
    group.add(textMesh);
  }

  // Apply scene position
  const pos = config.scenePosition || { x: 0, y: 0, z: 0 };
  group.position.set(pos.x, pos.y, pos.z);

  // Cleanup resources
  group.userData.cleanup = () => {
    geom.dispose();
    mat.dispose();
    tex.dispose();
  };

  group.userData.handlers = {};

  return group;
}
